//
// Per-proposal public tally key record.
//
// One Paillier public key per proposal, generated by that proposal's
// DKG ceremony and installed on chain by the dkg_key_activation
// transaction. Every ballot for the proposal is encrypted under this
// key. The tally committee is a subset of the proposal's DKG
// shareholders selected at voting_end_height; it is not part of this
// record.
//
// The existing dao_tally_key_record remains on the wire. This split
// representation is additive; no existing byte layout is changed.

#pragma once

#include <cstdint>
#include <vector>

#include "crypto/hash.h"
#include "governance/dao_paillier.h"

